from pathlib import Path

ROOT = Path.cwd()
if not (ROOT / "app").is_dir() or not (ROOT / "tests").is_dir():
    raise SystemExit("Run this script from the AI-Dev-Team repository root.")

files = {'app/tools/filesystem.py': 'from __future__ import annotations\n\nfrom pathlib import Path\n\n\nclass FilesystemTool:\n    """Safe filesystem operations constrained to a workspace."""\n\n    def __init__(self, workspace: str | Path) -> None:\n        self.workspace = Path(workspace).resolve()\n        self.workspace.mkdir(parents=True, exist_ok=True)\n\n    def safe_path(self, relative_path: str | Path) -> Path:\n        path = (self.workspace / Path(relative_path)).resolve()\n        try:\n            path.relative_to(self.workspace)\n        except ValueError as exc:\n            raise ValueError("Path escapes the workspace.") from exc\n        return path\n\n    def list_files(self) -> list[str]:\n        return sorted(\n            str(p.relative_to(self.workspace)).replace("\\\\", "/")\n            for p in self.workspace.rglob("*")\n            if p.is_file()\n        )\n\n    def read_file(self, relative_path: str) -> str:\n        return self.safe_path(relative_path).read_text(encoding="utf-8")\n\n    def write_file(self, relative_path: str, content: str) -> str:\n        if not isinstance(content, str):\n            raise TypeError("File content must be a string.")\n        path = self.safe_path(relative_path)\n        path.parent.mkdir(parents=True, exist_ok=True)\n        path.write_text(content, encoding="utf-8")\n        return str(path.relative_to(self.workspace)).replace("\\\\", "/")\n', 'app/tools/terminal.py': 'from __future__ import annotations\n\nimport subprocess\nfrom pathlib import Path\nfrom typing import Sequence\n\n\nclass TerminalTool:\n    """Run approved commands inside a workspace."""\n\n    def __init__(self, workspace: str | Path) -> None:\n        self.workspace = Path(workspace).resolve()\n        self.workspace.mkdir(parents=True, exist_ok=True)\n\n    def run(\n        self,\n        command: Sequence[str],\n        timeout: int = 120,\n    ) -> dict:\n        if not command:\n            raise ValueError("Command cannot be empty.")\n\n        completed = subprocess.run(\n            list(command),\n            cwd=self.workspace,\n            capture_output=True,\n            text=True,\n            timeout=timeout,\n            shell=False,\n        )\n\n        return {\n            "command": list(command),\n            "exit_code": completed.returncode,\n            "stdout": completed.stdout,\n            "stderr": completed.stderr,\n            "status": "passed" if completed.returncode == 0 else "failed",\n        }\n', 'app/tools/git.py': 'from __future__ import annotations\n\nimport subprocess\nfrom pathlib import Path\n\n\nclass GitTool:\n    """Read-only Git inspection for an agent workspace."""\n\n    def __init__(self, workspace: str | Path) -> None:\n        self.workspace = Path(workspace).resolve()\n\n    def _run(self, *args: str) -> dict:\n        completed = subprocess.run(\n            ["git", *args],\n            cwd=self.workspace,\n            capture_output=True,\n            text=True,\n            timeout=30,\n            shell=False,\n        )\n        return {\n            "command": ["git", *args],\n            "exit_code": completed.returncode,\n            "stdout": completed.stdout,\n            "stderr": completed.stderr,\n            "status": "passed" if completed.returncode == 0 else "failed",\n        }\n\n    def status(self) -> dict:\n        return self._run("status", "--short", "--branch")\n\n    def diff(self) -> dict:\n        return self._run("diff", "--")\n', 'tests/test_workspace_tools.py': 'from pathlib import Path\n\nfrom app.tools.filesystem import FilesystemTool\nfrom app.tools.terminal import TerminalTool\n\n\ndef test_filesystem_tool_is_workspace_safe(tmp_path: Path) -> None:\n    tool = FilesystemTool(tmp_path / "workspace")\n    assert tool.write_file("src/example.py", "VALUE = 1\\n") == "src/example.py"\n    assert tool.read_file("src/example.py") == "VALUE = 1\\n"\n    assert "src/example.py" in tool.list_files()\n\n\ndef test_filesystem_tool_rejects_escape(tmp_path: Path) -> None:\n    tool = FilesystemTool(tmp_path / "workspace")\n    try:\n        tool.safe_path("../outside.txt")\n    except ValueError:\n        pass\n    else:\n        raise AssertionError("Workspace escape was not rejected.")\n\n\ndef test_terminal_tool_runs_inside_workspace(tmp_path: Path) -> None:\n    tool = TerminalTool(tmp_path / "workspace")\n    result = tool.run(["python", "-c", "print(\'team-tool-ok\')"])\n    assert result["exit_code"] == 0\n    assert "team-tool-ok" in result["stdout"]\n'}
for relative, content in files.items():
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    print(f"UPDATED {relative}")

print("\nV0.3 tool upgrade installed.")
print("Next: python -m pytest -q")
